import{_ as i,o as u,c as n,a2 as t}from"./chunks/framework.CqpfiAoK.js";const w=JSON.parse('{"title":"Sheria ya Kulinda Mazingira","description":"","frontmatter":{},"headers":[],"relativePath":"sw/46-环境保护法.md","filePath":"sw/46-环境保护法.md","lastUpdated":1789183869000}'),h={name:"sw/46-环境保护法.md"};function m(l,a,o,e,k,r){return u(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="sheria-ya-kulinda-mazingira" tabindex="-1">Sheria ya Kulinda Mazingira <a class="header-anchor" href="#sheria-ya-kulinda-mazingira" aria-label="Permalink to &quot;Sheria ya Kulinda Mazingira&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mradi</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya hati</td><td>46</td></tr><tr><td>Moduli</td><td>Mfumo wa Kisheria na Muundo wa Usimamizi</td></tr><tr><td>Maneno muhimu ya msingi</td><td>Kulinda Mazingira, Asili ya Ulimwengu, Usawa wa Ikolojia, Maendeleo ya Kudumu, Kuzuia na Kudhibiti Uchafuzi</td></tr></tbody></table><h2 id="_1-lengo-la-kisheria-na-kanuni-za-msingi" tabindex="-1">1. Lengo la Kisheria na Kanuni za Msingi <a class="header-anchor" href="#_1-lengo-la-kisheria-na-kanuni-za-msingi" aria-label="Permalink to &quot;1. Lengo la Kisheria na Kanuni za Msingi&quot;">​</a></h2><p>《Sheria ya Kulinda Mazingira》 ni moja ya sheria tano za msingi za ustaarabu wa usawa wa nanga, na lengo lake ni kulinda mazingira ya ikolojia na asili ya ulimwengu ya Hengyuanzhou, kuanzisha dhana ya usimamizi wa mazingira ya &quot;mageuzi ya usawa, maendeleo ya kudumu&quot;, kuzuia uharibifu wa mfumo wa ikolojia wa ulimwengu unaosababishwa na uchimbaji wa mauaji, na kulinda msingi wa kuishi kwa maendeleo ya pamoja ya kila kabila.</p><p>Sheria hii inaweka kanuni zifuatazo za msingi:</p><table tabindex="0"><thead><tr><th>Kanuni</th><th>Maudhui</th></tr></thead><tbody><tr><td>Kanuni ya Kulinda Asili</td><td>Asili ya ulimwengu ni msingi wa maisha yote na mageuzi, lazima ilindwe kwa kipaumbele, na uchimbaji wa uharibifu umekatazwa</td></tr><tr><td>Kanuni ya Usawa wa Ikolojia</td><td>Binadamu na asili, kila kabila na mfumo wa ikolojia wako katika uhusiano wa usawa, na kuharibu ikolojia ni kuharibu msingi wa kuishi mwenyewe</td></tr><tr><td>Kanuni ya Kudumu</td><td>Shughuli zote za uchimbaji lazima zizingatie maslahi ya vizazi vya sasa na vijavyo, na kupinga uchimbaji wa kutosha kabisa</td></tr><tr><td>Kanuni ya Kuzuia Kwa Msingi</td><td>Kulinda mazingira kunazingatia kuzuia kwa msingi, kujenga mfumo wa tathmini ya athari ya mazingira, na kuzuia utukufu wa uchafuzi</td></tr><tr><td>Kanuni ya Wajibu wa Mwachafuzi</td><td>Mada inayosababisha uchafuzi wa mazingira na uharibifu wa ikolojia lazima ibebi wajibu wa usafi wa fidia</td></tr><tr><td>Kanuni ya Kushiriki kwa Umma</td><td>Kuchochea umma kushiriki katika kulinda mazingira, kuhakikisha haki ya umma ya kujua habari za mazingira na haki ya kushiriki</td></tr><tr><td>Kanuni ya Ushirikiano wa Kati ya Viwango</td><td>Kulinda mazingira kunakuendeleza kupitia ushirikiano wa kati ya viwango, kujenga mfumo wa ushirikiano wa usimamizi wa mazingira wa kati ya viwango</td></tr></tbody></table><h2 id="_2-eneo-la-kulinda-mazingira" tabindex="-1">2. Eneo la Kulinda Mazingira <a class="header-anchor" href="#_2-eneo-la-kulinda-mazingira" aria-label="Permalink to &quot;2. Eneo la Kulinda Mazingira&quot;">​</a></h2><p>Eneo la mazingira lililolindwa na sheria hii linajumuisha mifumo yote ya ikolojia na vitu vya mazingira ndani ya Hengyuanzhou:</p><ol><li><strong>Mazingira ya Hewa</strong>: Inajumuisha anga la kila sayari, msongamano wa nishati na usawa wa viungo vya safu ya nishati.</li><li><strong>Mazingira ya Maji</strong>: Inajumuisha ubora na kiasi cha maji ya juu ya ardhi, maji ya chini ya ardhi, bahari, na maji ya nishati kati ya viwango.</li><li><strong>Mazingira ya Mchanga</strong>: Inajumuisha ubora na rutuba ya mchanga wa nchi kavu na mishipa ya madini ya rasilimali za mazoezi.</li><li><strong>Anuwai ya Viumbe</strong>: Inajumuisha kulinda spishi na makazi ya wanyama na mimea yote, vijidudu, na maisha ya ajabu.</li><li><strong>Mazingira ya Nishati</strong>: Inajumuisha msongamano na usawa wa usambazaji wa roho ya mbingu na ardhi, nishati ya asili, na vipande vya sheria.</li><li><strong>Mazingira ya Nafasi</strong>: Inajumuisha uthabiti wa nafasi ya viwango, mapasuko ya nafasi, na usalama wa mazingira wa nafasi iliyosongezwa.</li><li><strong>Mazingira ya Kikoa cha Fahamu</strong>: Inajumuisha usafi wa taarifa za nafasi ya fahamu ya pamoja na kuzuia uchafuzi wa kiroho.</li></ol><h2 id="_3-mifumo-kuu" tabindex="-1">3. Mifumo Kuu <a class="header-anchor" href="#_3-mifumo-kuu" aria-label="Permalink to &quot;3. Mifumo Kuu&quot;">​</a></h2><h3 id="_1-mfumo-wa-tathmini-ya-athari-ya-mazingira" tabindex="-1">(1) Mfumo wa Tathmini ya Athari ya Mazingira <a class="header-anchor" href="#_1-mfumo-wa-tathmini-ya-athari-ya-mazingira" aria-label="Permalink to &quot;(1) Mfumo wa Tathmini ya Athari ya Mazingira&quot;">​</a></h3><p>Miradi yote ya maendeleo na ujenzi ambayo yanaweza kuwa na athari kubwa kwa mazingira lazima ipite tathmini ya athari ya mazingira kabla ya kuanza kazi. Maudhui ya tathmini yanajumuisha: athari ya mradi kwa vitu vya mazingira kama vile hewa, maji, mchanga, viumbe, nishati, nafasi, n.k., hatua za kuzuia na kupunguza, tathmini ya hatari ya mazingira, n.k. Miradi ambayo haijapita tathmini ya athari ya mazingira haiwezi kuanza ujenzi.</p><h3 id="_2-mfumo-wa-leseni-ya-uchujaji-na-udhibiti-wa-jumla-ya-kiasi" tabindex="-1">(2) Mfumo wa Leseni ya Uchujaji na Udhibiti wa Jumla ya Kiasi <a class="header-anchor" href="#_2-mfumo-wa-leseni-ya-uchujaji-na-udhibiti-wa-jumla-ya-kiasi" aria-label="Permalink to &quot;(2) Mfumo wa Leseni ya Uchujaji na Udhibiti wa Jumla ya Kiasi&quot;">​</a></h3><p>Serikali inatekeleza usimamizi wa leseni na udhibiti wa jumla ya kiasi kwa uchujaji wa vichafuzi. Vitengo vya uchujaji wa uchafuzi lazima vipate leseni ya uchujaji wa uchafuzi, na kuchuja vichafuzi kulingana na aina, msongamano, na jumla ya kiasi vilivyoainishwa katika leseni. Serikali inabainisha jumla ya kiasi cha uchujaji wa vichafuzi vya kila eneo, kila kiwango kulingana na uwezo wa kubeba wa mazingira, na kugawanya kwa hatua kwa hatua kwa utekelezaji.</p><h3 id="_3-mfumo-wa-mstari-mwekundu-wa-kulinda-ikolojia" tabindex="-1">(3) Mfumo wa Mstari Mwekundu wa Kulinda Ikolojia <a class="header-anchor" href="#_3-mfumo-wa-mstari-mwekundu-wa-kulinda-ikolojia" aria-label="Permalink to &quot;(3) Mfumo wa Mstari Mwekundu wa Kulinda Ikolojia&quot;">​</a></h3><p>Serikali inabainisha mstari mwekundu wa kulinda ikolojia katika maeneo yenye thamani maalum ya ikolojia, ikiwa ni pamoja na:</p><table tabindex="0"><thead><tr><th>Aina ya Mstari Mwekundu</th><th>Maudhui ya Kulinda</th></tr></thead><tbody><tr><td>Eneo la Kulinda Asili</td><td>Eneo kuu la uzalishaji wa nishati ya asili ya ulimwengu, shughuli zote za uchimbaji zimekatazwa</td></tr><tr><td>Makazi ya Spishi</td><td>Makazi kuu ya spishi adimu na hatarini kutoweka, uharibifu na kuingilia kati zimekatazwa</td></tr><tr><td>Eneo la Kizuizi cha Ikolojia</td><td>Mfumo muhimu wa ikolojia unaodumusha usawa wa ikolojia wa eneo, uchimbaji umekabiliwa</td></tr><tr><td>Mahali Pafu pa Mazoezi</td><td>Eneo tajiri nishati linalo na thamani maalum ya mazoezi, inatekeleza matumizi ya kulinda</td></tr><tr><td>Kanda ya Mipaka ya Viwango</td><td>Kanda ya mpito wa ikolojia kati ya viwango, uchimbaji wa uharibifu wa nafasi umekatazwa</td></tr></tbody></table><h3 id="_4-mfumo-wa-ufuatiliaji-na-tahadhari-ya-mazingira" tabindex="-1">(4) Mfumo wa Ufuatiliaji na Tahadhari ya Mazingira <a class="header-anchor" href="#_4-mfumo-wa-ufuatiliaji-na-tahadhari-ya-mazingira" aria-label="Permalink to &quot;(4) Mfumo wa Ufuatiliaji na Tahadhari ya Mazingira&quot;">​</a></h3><p>Serikali inajenga mtandao wa ufuatiliaji wa mazingira unaofunika ulimwengu mzima, na kufuatilia muda halisi hali ya mabadiliko ya kila kipengele cha mazingira. Kwa matukio makubwa ya uchafuzi wa mazingira na uharibifu wa ikolojia yanayoweza kutokea, inajenga mfumo wa tahadhari, inatoa habari za tahadhari kwa wakati na kuanzisha majibu ya dharura.</p><h3 id="_5-mfumo-wa-fidia-ya-ikolojia" tabindex="-1">(5) Mfumo wa Fidia ya Ikolojia <a class="header-anchor" href="#_5-mfumo-wa-fidia-ya-ikolojia" aria-label="Permalink to &quot;(5) Mfumo wa Fidia ya Ikolojia&quot;">​</a></h3><p>Maeneo na vikundi ambavyo uchimbaji umekabiliwa kutokana na kulinda mazingira vina haki ya kupokea fidia ya ikolojia. Fedha za fidia ya ikolojia zinatolewa kutoka akiba ya umma na mapato ya uchimbaji wa rasilimali, na zinatumika kwa maendeleo ya kiuchumi ya eneo la fidia na kuboresha maisha ya wakazi.</p><h2 id="_4-udhibiti-wa-mazingira-wa-shughuli-za-mazoezi" tabindex="-1">4. Udhibiti wa Mazingira wa Shughuli za Mazoezi <a class="header-anchor" href="#_4-udhibiti-wa-mazingira-wa-shughuli-za-mazoezi" aria-label="Permalink to &quot;4. Udhibiti wa Mazingira wa Shughuli za Mazoezi&quot;">​</a></h2><p>Athari ya shughuli za mazoezi kwa mazingira ni eneo maalum la kulinda mazingira la Hengyuanzhou, na sheria hii inaweka maalum masharti ya udhibiti:</p><ol><li><strong>Udhibiti wa Uchimbaji wa Nishati</strong>: Uchimbaji wa rasilimali za mazoezi lazima utimize kanuni ya kudumu, na uchimbaji wa uharibifu unaosababisha ukosefu wa nishati umekatazwa. Kiasi cha uchimbaji hakifai kuzidi kasi ya urejeshaji wa asili wa nishati ya eneo.</li><li><strong>Usimamizi wa Takataka za Mazoezi</strong>: Mabaki ya nishati, dawa za mazoezi zilizotupwa, vyombo vilivyoharibika, n.k. zinazotokea wakati wa mchakato wa mazoezi lazima zisibamwe kulingana na masharti, na kutupwa kwa hiari kusababisha uchafuzi wa nishati kunakatazwa.</li><li><strong>Tathmini ya Mazingira ya Mazoezi ya Juu</strong>: Mapambano na kufunga kwa wanaofanya mazoezi wa juu yanaweza kuwa na athari kubwa kwa mazingira ya karibu, na lazima yapite tathmini ya mazingira kabla na kuchukua hatua za ulinzi.</li><li><strong>Leseni ya Uchimbaji wa Viwango</strong>: Uchimbaji wa viwango vipya lazima upite tathmini ya mazingira na uchunguzi wa ikolojia, na unaweza kufanyika baada ya kuandaa mpango wa kulinda ikolojia.</li><li><strong>Kulinda Makazi ya Maisha ya Ajabu</strong>: Makazi ya maisha ya ajabu yameingizwa katika mstari mwekundu wa kulinda ikolojia, na kuchunguza na kuchimbaji bila leseni kunakatazwa.</li></ol><h2 id="_5-wajibu-wa-kisheria" tabindex="-1">5. Wajibu wa Kisheria <a class="header-anchor" href="#_5-wajibu-wa-kisheria" aria-label="Permalink to &quot;5. Wajibu wa Kisheria&quot;">​</a></h2><p>Shughuli zinazovunja masharti ya sheria hii zitabeba wajibu ufuatao kulingana na ukubwa wa makosa:</p><ul><li>Kuanza ujenzi bila kupita tathmini ya athari ya mazingira, kuamriwa kusimamisha ujenzi, kurejesha hali ya asili na kupigwa faini.</li><li>Kuchuja vichafuzi vya kuzidi kiwango, kuamriwa kutibu kwa muda na kupigwa faini, katika visa vizito kuamriwa kufunga biashara.</li><li>Kuharibu mstari mwekundu wa kulinda ikolojia, kuamriwa kurejesha hali ya asili na kupigwa faini, katika visa vizito wajibu wa jinai unafuatiliwa.</li><li>Kuchimba rasilimali za mazoezi kwa uharibifu, kunyakuliwa mapato ya kikatili na kupigwa faini, leseni ya uchimbaji inakatiwa.</li><li>Kusababisha ajali makubwa ya uchafuzi wa mazingira, kubeba wajibu wa fidia, ikiwa inajenga uhalishi wajibu wa jinai unafuatiliwa.</li><li>Wafanyakazi wa ufuatiliaji wa mazingira wanaopuuza wajibu, kutumia nguvu za kisiasa vibaya, wanapigwa faini, ikiwa inajenga uhalishi wajibu wa jinai unafuatiliwa.</li></ul><h2 id="_6-kushiriki-kwa-umma-na-kesi-ya-manufaa-ya-umma-ya-mazingira" tabindex="-1">6. Kushiriki kwa Umma na Kesi ya Manufaa ya Umma ya Mazingira <a class="header-anchor" href="#_6-kushiriki-kwa-umma-na-kesi-ya-manufaa-ya-umma-ya-mazingira" aria-label="Permalink to &quot;6. Kushiriki kwa Umma na Kesi ya Manufaa ya Umma ya Mazingira&quot;">​</a></h2><p>Umma ana haki ya kushiriki katika kulinda mazingira, na njia maalum zinajumuisha:</p><ol><li>Kutoa maoni na mapendekezo kuhusu mradi wa tathmini ya athari ya mazingira.</li><li>Kuripoti na kulalamika kuhusu tabia zinazochafusha mazingira na kuharibu ikolojia.</li><li>Kuanzisha mashirika ya kulinda mazingira kulingana na sheria, kushiriki katika ufuatiliaji wa mazingira na shughuli za manufaa ya umma.</li><li>Kwa tabia zinazochafusha mazingira, kuharibu ikolojia na kudhuru manufaa ya umma, mashirika ya kulinda mazingira yanaweza kuleta kesi ya manufaa ya umma ya mazingira katika Korti ya Usawa.</li></ol><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>《Sheria ya Kulinda Mazingira》 ni uhakikisho wa kisheria wa dhana ya maendeleo ya kudumu ya ustaarabu wa usawa wa nanga. Kupitia kujenga mifumo kama vile tathmini ya athari ya mazingira, mstari mwekundu wa kulinda ikolojia, na udhibiti wa jumla ya kiasi, inajumuisha kulinda mazingira katika shughuli zote za uchimbaji na mazoezi, inahakikisha uendelevu wa asili ya ulimwengu na mfumo wa ikolojia, na kulinda msingi wa kuishi wa milele kwa maendeleo ya pamoja ya kila kabila.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Kanuni za Msingi za Katiba ya Usawa)</li><li>39-住房与环境保障 (Uhakikisho wa Makazi na Mazingira)</li><li>15-能量循环与转化法则 (Sheria ya Mzunguko na Mabadiliko ya Nishati)</li><li>53-奇特生命识别标准 (Kiwangoo cha Utambuzi wa Maisha ya Ajabu)</li></ul>',34)])])}const z=i(h,[["render",m]]);export{w as __pageData,z as default};
